-- 259: Create the PSEA info page (psea.html), modelled on the NUS PSEA page:
--      what PSEA is, what it covers, and a visual withdrawal flow.

INSERT INTO cms_page (title, root_template, identifier, content_heading, content, meta_description, is_active, sort_order, creation_time, update_time) SELECT 'Post-Secondary Education Account (PSEA)','one_column','psea.html','',,,1,0,NOW(),NOW() FROM dual WHERE NOT EXISTS (SELECT 1 FROM (SELECT page_id FROM cms_page WHERE identifier='psea.html') t);

UPDATE cms_page SET , is_active=1 WHERE identifier='psea.html';

INSERT INTO cms_page_store (page_id, store_id) SELECT p.page_id,0 FROM cms_page p WHERE p.identifier='psea.html' AND NOT EXISTS (SELECT 1 FROM cms_page_store s WHERE s.page_id=p.page_id);
